from django.db import migrations

SQL="-- M2 R4/R5: enforce the task-side evidence invariant at final transaction state.\nCREATE OR REPLACE FUNCTION public.m2_task_final_completion_integrity()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE current_state text; finished timestamptz; current_kind text;\n        completion_id uuid; attestation_id uuid; completion_actor uuid; attestation_actor uuid;\nBEGIN\n  SELECT execution_state,completed_at,kind INTO current_state,finished,current_kind\n  FROM public.onboarding_task WHERE id=NEW.id;\n  IF current_state='COMPLETED' THEN\n    SELECT c.id,c.manager_attestation_id,c.completed_by_id,a.actor_id\n    INTO completion_id,attestation_id,completion_actor,attestation_actor\n    FROM public.onboarding_taskcompletion c\n    JOIN public.onboarding_managerattestation a ON a.id=c.manager_attestation_id\n    WHERE c.task_id=NEW.id AND a.task_id=NEW.id\n          AND c.evidence_type='MANAGER_PREPARATION';\n    IF current_kind IS DISTINCT FROM 'MANAGER_PREPARATION'\n        OR finished IS NULL OR completion_id IS NULL\n        OR completion_actor IS DISTINCT FROM attestation_actor THEN\n      RAISE EXCEPTION 'M2 completed task requires matching accepted evidence'\n        USING ERRCODE='23514';\n    END IF;\n  ELSIF finished IS NOT NULL THEN\n    RAISE EXCEPTION 'M2 incomplete task cannot have completed_at'\n      USING ERRCODE='23514';\n  END IF;\n  RETURN NULL;\nEND; $$;\n\n-- Deferred so the ordinary atomic command may insert evidence and task state\n-- in either order, but may not commit an unsupported/evidence-less completion.\nCREATE CONSTRAINT TRIGGER m2_task_final_completion_integrity\nAFTER INSERT OR UPDATE ON public.onboarding_task\nDEFERRABLE INITIALLY DEFERRED FOR EACH ROW\nEXECUTE FUNCTION public.m2_task_final_completion_integrity();\n\nCREATE OR REPLACE FUNCTION public.m2_protect_snapshot_schedule()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nBEGIN\n  IF NEW.available_at IS DISTINCT FROM OLD.available_at\n     OR NEW.due_at IS DISTINCT FROM OLD.due_at THEN\n    RAISE EXCEPTION 'M2 instantiated task schedule is immutable' USING ERRCODE='23514';\n  END IF;\n  IF OLD.execution_state='COMPLETED'\n     AND (NEW.completed_at IS DISTINCT FROM OLD.completed_at\n          OR NEW.work_started_at IS DISTINCT FROM OLD.work_started_at) THEN\n    RAISE EXCEPTION 'M2 accepted completion metadata is immutable' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND; $$;\nCREATE TRIGGER m2_task_schedule_immutable\nBEFORE UPDATE OF available_at,due_at,completed_at,work_started_at\nON public.onboarding_task FOR EACH ROW\nEXECUTE FUNCTION public.m2_protect_snapshot_schedule();\n\nCREATE OR REPLACE FUNCTION public.m2_protect_activated_case_template()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nBEGIN\n  IF OLD.activated_at IS NOT NULL AND\n      (NEW.template_version_id IS DISTINCT FROM OLD.template_version_id\n       OR NEW.activated_at IS DISTINCT FROM OLD.activated_at) THEN\n    RAISE EXCEPTION 'M2 activated case template binding is immutable' USING ERRCODE='23514';\n  END IF;\n  RETURN NEW;\nEND; $$;\nCREATE TRIGGER m2_activated_case_template_immutable\nBEFORE UPDATE OF template_version_id,activated_at\nON public.onboarding_onboardingcase FOR EACH ROW\nEXECUTE FUNCTION public.m2_protect_activated_case_template();"
REVERSE_SQL="DROP TRIGGER IF EXISTS m2_activated_case_template_immutable ON public.onboarding_onboardingcase;\nDROP FUNCTION IF EXISTS public.m2_protect_activated_case_template();\nDROP TRIGGER IF EXISTS m2_task_schedule_immutable ON public.onboarding_task;\nDROP FUNCTION IF EXISTS public.m2_protect_snapshot_schedule();\nDROP TRIGGER IF EXISTS m2_task_final_completion_integrity ON public.onboarding_task;\nDROP FUNCTION IF EXISTS public.m2_task_final_completion_integrity();"

class Migration(migrations.Migration):
    dependencies=[('onboarding','0007_snapshot_evidence_guards')]
    operations=[migrations.RunSQL(SQL,REVERSE_SQL)]
